// NOTA: Este arquivo deve estar em `supabase/functions/process-pdf-statement/index.ts`
import { GoogleGenAI } from "https://esm.sh/@google/genai@0.12.0";
import { encodeBase64 } from "https://deno.land/std@0.224.0/encoding/base64.ts";

declare const Deno: any;

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY");

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    if (!GEMINI_API_KEY) {
      throw new Error("GEMINI_API_KEY not set in Supabase Edge Functions secrets.");
    }

    // Recebe fileUrl em vez de fileData (base64) para evitar limites de tamanho de corpo da requisição
    const { fileUrl, mimeType, categoryNames } = await req.json();

    if (!fileUrl || !mimeType) {
        return new Response(JSON.stringify({ error: "fileUrl and mimeType are required." }), {
            status: 400,
            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
        });
    }

    // Baixa o arquivo do Storage (usando a URL assinada)
    const fileResponse = await fetch(fileUrl);
    if (!fileResponse.ok) {
        throw new Error(`Failed to download file from storage: ${fileResponse.statusText}`);
    }
    const arrayBuffer = await fileResponse.arrayBuffer();

    // Converte para base64 dentro da Edge Function
    const base64Data = encodeBase64(arrayBuffer);

    const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });

    const categoriesStr = categoryNames && categoryNames.length > 0 ? categoryNames.join(', ') : 'Alimentação, Transporte, Moradia, Saúde, Lazer, Outros';

    const systemInstruction = `
    Você é um especialista em contabilidade e extração de dados bancários.
    Sua tarefa é analisar o arquivo PDF fornecido (que é um extrato bancário, possivelmente do Banco do Brasil ou similar) e extrair todos os lançamentos financeiros.

    Regras de Extração:
    1. Ignore linhas de saldo anterior, saldo parcial, saldo bloqueado ou totalizadores. Foque apenas nas transações individuais.
    2. Identifique a DATA (formato YYYY-MM-DD). Se o ano não estiver explícito no lançamento, use o ano atual ou tente inferir do cabeçalho.
    3. Identifique a DESCRIÇÃO (texto explicativo do lançamento).
    4. Identifique o VALOR (numérico absoluto).
    5. Determine a NATUREZA ('RECEITA' para créditos/depósitos, 'DESPESA' para débitos/saques/pagamentos).
       - No Banco do Brasil, letras 'C' ao lado do valor indicam Crédito (Receita) e 'D' indicam Débito (Despesa). Sinais de '-' também indicam despesa.
    6. Tente categorizar a transação baseado na descrição, escolhendo a melhor opção desta lista: [${categoriesStr}]. Se não tiver certeza, use 'Outros'.

    Formato de Saída:
    Retorne APENAS um JSON válido contendo um objeto com a chave "transactions", que é um array de objetos.
    Exemplo:
    {
      "transactions": [
        { "date": "2024-05-12", "description": "SUPERMERCADO EXTRA", "value": 150.50, "nature": "DESPESA", "categoryName": "Alimentação" },
        { "date": "2024-05-15", "description": "PIX RECEBIDO JOAO", "value": 500.00, "nature": "RECEITA", "categoryName": "Outros" }
      ]
    }
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview', 
        contents: {
            parts: [
                { text: "Analise este extrato bancário e extraia os lançamentos conforme as instruções." },
                { inlineData: { mimeType: mimeType, data: base64Data } }
            ]
        },
        config: {
            systemInstruction: systemInstruction,
            responseMimeType: "application/json"
        }
    });

    if (!response.text) {
      throw new Error("A IA não retornou uma resposta de texto.");
    }

    let jsonResponse;
    try {
        jsonResponse = JSON.parse(response.text);
    } catch (e) {
        console.error("Falha ao fazer parse do JSON da IA:", response.text);
        throw new Error("A IA retornou um formato inválido.");
    }

    return new Response(JSON.stringify(jsonResponse), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 200,
    });

  } catch (error) {
    console.error("Error in 'process-pdf-statement' edge function:", error);
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500,
    });
  }
});

import React, { useState, useEffect } from 'react';
