import React, { createContext, useState, useEffect, ReactNode, useMemo } from 'react';
import { BankAccount, Category, Transaction, Document, Attachment, NewAttachment, KeepAliveLog } from '../types';
import { supabase, base64ToBlob } from '../supabase/client';

interface AppContextType {
  isLoading: boolean;
  accounts: BankAccount[];
  addAccount: (account: Omit<BankAccount, 'id'>) => Promise<BankAccount | null>;
  updateAccount: (account: BankAccount) => Promise<void>;
  deleteAccount: (id: string) => Promise<void>;
  getAccountById: (id: string) => BankAccount | undefined;

  categories: Category[];
  addCategory: (category: Omit<Category, 'id'>) => Promise<void>;
  addCategoriesBatch: (categories: Omit<Category, 'id'>[]) => Promise<void>;
  updateCategory: (category: Category) => Promise<void>;
  deleteCategory: (id: string) => Promise<void>;

  transactions: Transaction[];
  addTransaction: (transaction: Omit<Transaction, 'id'>, newAttachments?: NewAttachment[]) => Promise<void>;
  addTransactionsBatch: (transactions: Omit<Transaction, 'id'>[]) => Promise<void>;
  updateTransaction: (transaction: Transaction, newAttachments?: NewAttachment[]) => Promise<void>;
  deleteTransaction: (id: string) => Promise<void>;

  documents: Document[];
  addDocument: (title: string, fileName: string, base64Data: string) => Promise<void>;
  deleteDocument: (id: string) => Promise<void>;

  keepAliveLogs: KeepAliveLog[];

  calculateCurrentBalance: (accountId: string) => number;
}

export const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [keepAliveLogs, setKeepAliveLogs] = useState<KeepAliveLog[]>([]);

  const fetchData = async () => {
    setIsLoading(true);
    try {
      const [accountsRes, categoriesRes, transactionsRes, documentsRes, keepAliveLogsRes] = await Promise.all([
        supabase.from('accounts').select('*'),
        supabase.from('categories').select('*'),
        supabase.from('transactions').select('*').order('date', { ascending: false }),
        supabase.from('documents').select('*').order('created_at', { ascending: false }),
        supabase.from('keep_alive_logs').select('*').order('pinged_at', { ascending: false })
      ]);

      if (accountsRes.error) console.error("Error fetching accounts:", accountsRes.error);
      if (categoriesRes.error) console.error("Error fetching categories:", categoriesRes.error);
      if (transactionsRes.error) console.error("Error fetching transactions:", transactionsRes.error);

      const typedAccounts = (accountsRes.data || []).map(a => ({...a, dataAbertura: a.dataAbertura.split('T')[0]}));
      const typedTransactions = (transactionsRes.data || []).map(t => ({...t, date: t.date.split('T')[0]}));

      setAccounts(typedAccounts);
      setCategories(categoriesRes.data || []);
      setTransactions(typedTransactions);
      setDocuments(documentsRes.data || []);
      setKeepAliveLogs(keepAliveLogsRes.data || []);

    } catch (error: any)
    {
      console.error("Error fetching initial data:", error.message || error);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Accounts CRUD
  const addAccount = async (accountData: Omit<BankAccount, 'id'>): Promise<BankAccount | null> => {
    const newAccount = { ...accountData, id: crypto.randomUUID() };
    const { data, error } = await supabase.from('accounts').insert(newAccount).select();
    if (error) {
      console.error("Error adding account:", error);
      return null;
    }
    if (data) {
      const createdAccount = data[0];
      setAccounts(prev => [...prev, createdAccount]);
      return createdAccount;
    }
    return null;
  };
  const updateAccount = async (updatedAccount: BankAccount) => {
    const { error } = await supabase.from('accounts').update(updatedAccount).eq('id', updatedAccount.id);
    if (error) return console.error("Error updating account:", error);
    setAccounts(prev => prev.map(acc => acc.id === updatedAccount.id ? updatedAccount : acc));
  };
  const deleteAccount = async (id: string) => {
    const { error } = await supabase.from('accounts').delete().eq('id', id);
    if (error) return console.error("Error deleting account:", error);
    setAccounts(prev => prev.filter(acc => acc.id !== id));
  };
  const getAccountById = (id: string) => accounts.find(acc => acc.id === id);

  // Categories CRUD
  const addCategory = async (categoryData: Omit<Category, 'id'>) => {
    const newCategory = { ...categoryData, id: crypto.randomUUID() };
    const { error } = await supabase.from('categories').insert(newCategory);
    if (error) return console.error("Error adding category:", error);
    setCategories(prev => [...prev, newCategory]);
  };
  const addCategoriesBatch = async (categoriesData: Omit<Category, 'id'>[]) => {
    const newCategories = categoriesData.map(c => ({ ...c, id: crypto.randomUUID() }));
    const { error } = await supabase.from('categories').insert(newCategories);
    if (error) {
        console.error("Error adding categories in batch:", error);
        throw error;
    }
    setCategories(prev => [...prev, ...newCategories].sort((a, b) => a.name.localeCompare(b.name)));
  };
  const updateCategory = async (updatedCategory: Category) => {
    const { error } = await supabase.from('categories').update(updatedCategory).eq('id', updatedCategory.id);
    if (error) return console.error("Error updating category:", error);
    setCategories(prev => prev.map(cat => cat.id === updatedCategory.id ? updatedCategory : cat));
  };
  const deleteCategory = async (id: string) => {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) {
      console.error("Error deleting category:", error.message);
      throw error;
    }
    setCategories(prev => prev.filter(cat => cat.id !== id));
  };

  // Transactions CRUD
  const handleAttachmentUpload = async (newAttachments: NewAttachment[]): Promise<Attachment[]> => {
    const uploadedAttachments: Attachment[] = [];
    for (const attachment of newAttachments) {
      // Create a clean file path
      const sanitizedName = attachment.name.replace(/[^a-zA-Z0-9.-]/g, '_');
      const filePath = `public/${crypto.randomUUID()}-${sanitizedName}`;

      const { error: uploadError } = await supabase.storage
        .from('attachments')
        .upload(filePath, base64ToBlob(attachment.data, 'image/jpeg'));

      if (uploadError) {
        console.error('Error uploading attachment:', uploadError);
        continue;
      }

      const { data: { publicUrl } } = supabase.storage.from('attachments').getPublicUrl(filePath);
      uploadedAttachments.push({ id: attachment.id, name: attachment.name, url: publicUrl });
    }
    return uploadedAttachments;
  }

  const addTransaction = async (transactionData: Omit<Transaction, 'id'>, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const newTransaction = { ...transactionData, id: crypto.randomUUID(), attachments: uploadedAttachments };
    const { error } = await supabase.from('transactions').insert(newTransaction);
    if (error) return console.error("Error adding transaction:", error);
    setTransactions(prev => [newTransaction, ...prev].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const addTransactionsBatch = async (transactionsData: Omit<Transaction, 'id'>[]) => {
    const newTransactions = transactionsData.map(t => ({ ...t, id: crypto.randomUUID() }));
    const { error } = await supabase.from('transactions').insert(newTransactions);
    if (error) {
        console.error("Error adding transactions in batch:", error);
        throw error;
    }
    setTransactions(prev => [...prev, ...newTransactions].sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const updateTransaction = async (updatedTransactionData: Transaction, newAttachments: NewAttachment[] = []) => {
    const uploadedAttachments = await handleAttachmentUpload(newAttachments);
    const finalAttachments = [...(updatedTransactionData.attachments || []), ...uploadedAttachments];
    const transactionToUpdate = { ...updatedTransactionData, attachments: finalAttachments };
    const { error } = await supabase.from('transactions').update(transactionToUpdate).eq('id', transactionToUpdate.id);
    if (error) return console.error("Error updating transaction:", error);
    setTransactions(prev => prev.map(t => t.id === transactionToUpdate.id ? transactionToUpdate : t).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()));
  };
  const deleteTransaction = async (id: string) => {
    const transactionToDelete = transactions.find(t => t.id === id);
    if (transactionToDelete?.attachments) {
      for (const attachment of transactionToDelete.attachments) {
        try {
          const url = new URL(attachment.url);
          const storagePath = url.pathname.split('/attachments/')[1];
          await supabase.storage.from('attachments').remove([storagePath]);
        } catch(e) { console.error("Failed to parse or delete attachment from storage:", e) }
      }
    }
    const { error } = await supabase.from('transactions').delete().eq('id', id);
    if (error) {
        console.error("Error deleting transaction:", error);
        // Lança o erro para que a UI possa reagir (ex: mostrar um alerta)
        throw error;
    }
    setTransactions(prev => prev.filter(t => t.id !== id));
  };

  // Documents CRUD
  const addDocument = async (title: string, fileName: string, base64Data: string) => {
      const sanitizedName = fileName.replace(/[^a-zA-Z0-9.-]/g, '_');
      const storagePath = `documents/${crypto.randomUUID()}-${sanitizedName}`;

      const { error: uploadError } = await supabase.storage
          .from('attachments')
          .upload(storagePath, base64ToBlob(base64Data, 'image/jpeg'));

      if (uploadError) {
          console.error("Error uploading document:", uploadError);
          throw uploadError; // Re-throw to handle in UI
      }

      const newDocument = { title, file_name: fileName, storage_path: storagePath };
      const { data, error } = await supabase.from('documents').insert(newDocument).select();
      if (error) {
        console.error("Error saving document record:", error);
        // Try to cleanup file if DB insert fails
        await supabase.storage.from('attachments').remove([storagePath]);
        throw error;
      }
      if (data) setDocuments(prev => [data[0], ...prev]);
  };
  const deleteDocument = async (id: string) => {
      const docToDelete = documents.find(d => d.id === id);
      if (!docToDelete) return;

      const { error: storageError } = await supabase.storage.from('attachments').remove([docToDelete.storage_path]);
      if (storageError) console.error("Error deleting document from storage:", storageError);

      const { error: dbError } = await supabase.from('documents').delete().eq('id', id);
      if (dbError) return console.error("Error deleting document from DB:", dbError);

      setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const calculateCurrentBalance = useMemo(() => (accountId: string): number => {
    const account = accounts.find(acc => acc.id === accountId);
    if (!account) return 0;

    const accountTransactions = transactions.filter(t => t.accountId === accountId && t.type === 'checking_account');

    const balance = accountTransactions.reduce((acc, curr) => {
      if (curr.nature === 'RECEITA') {
        return acc + curr.value;
      }
      return acc - curr.value;
    }, 0);

    return balance;
  }, [accounts, transactions]);

  const contextValue = {
    isLoading,
    accounts, addAccount, updateAccount, deleteAccount, getAccountById,
    categories, addCategory, addCategoriesBatch, updateCategory, deleteCategory,
    transactions, addTransaction, addTransactionsBatch, updateTransaction, deleteTransaction,
    documents, addDocument, deleteDocument,
    keepAliveLogs,
    calculateCurrentBalance,
  };

  return (
    <AppContext.Provider value={contextValue}>
      {children}
    </AppContext.Provider>
  );
};

// NOTA: Este arquivo deve estar em `supabase/functions/process-pdf-statement/index.ts`
import { GoogleGenAI } from "https://esm.sh/@google/genai@0.12.0";
import { encodeBase64 } from "https://deno.land/std@0.224.0/encoding/base64.ts";
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

declare const Deno: any;

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY");
const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    if (!GEMINI_API_KEY || !SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
      throw new Error("Missing env vars: GEMINI_API_KEY, SUPABASE_URL, or SUPABASE_SERVICE_ROLE_KEY");
    }

    const requestData = await req.json();
    const { action } = requestData;

    // --- AÇÃO 1: Gerar URL de Upload Assinada (Proxy para contornar RLS) ---
    if (action === 'get_upload_url') {
        const { fileName } = requestData;
        if (!fileName) throw new Error("fileName is required for get_upload_url");

        const supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
        const filePath = `temp/${crypto.randomUUID()}-${fileName}`;

        // Cria uma URL assinada que permite fazer UPLOAD diretamente para o path especificado
        // Isso permite que o frontend faça upload sem estar logado (bypass RLS)
        const { data, error } = await supabaseAdmin.storage
            .from('attachments')
            .createSignedUploadUrl(filePath);

        if (error) throw error;

        return new Response(JSON.stringify({ 
            token: data.token, 
            path: data.path,
            signedUrl: data.signedUrl 
        }), {
            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
            status: 200,
        });
    }

    // --- AÇÃO 2: Processar Arquivo (IA) ---
    if (action === 'process') {
        const { filePath, mimeType, categoryNames } = requestData;

        if (!filePath || !mimeType) {
            throw new Error("filePath and mimeType are required for process action.");
        }

        const supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

        // Baixa o arquivo usando credenciais de admin (bypass RLS de leitura)
        const { data: fileData, error: downloadError } = await supabaseAdmin.storage
            .from('attachments')
            .download(filePath);

        if (downloadError) {
             throw new Error(`Failed to download file: ${downloadError.message}`);
        }

        const arrayBuffer = await fileData.arrayBuffer();
        const base64Data = encodeBase64(arrayBuffer);
        const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });

        const categoriesStr = categoryNames && categoryNames.length > 0 ? categoryNames.join(', ') : 'Alimentação, Transporte, Moradia, Saúde, Lazer, Outros';

        const systemInstruction = `
        Você é um especialista em contabilidade e extração de dados bancários.
        Sua tarefa é analisar o arquivo PDF fornecido e extrair todos os lançamentos financeiros.

        Regras:
        1. Ignore linhas de saldo. Foque nas transações.
        2. Identifique DATA (YYYY-MM-DD), DESCRIÇÃO, VALOR (numérico) e NATUREZA ('RECEITA' ou 'DESPESA').
        3. Banco do Brasil: 'C' = Receita, 'D' = Despesa.
        4. Categorize baseado em: [${categoriesStr}]. Se incerto, use 'Outros'.

        Saída JSON:
        {
          "transactions": [
            { "date": "2024-05-12", "description": "MERCADO", "value": 150.50, "nature": "DESPESA", "categoryName": "Alimentação" }
          ]
        }
        `;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview', 
            contents: {
                parts: [
                    { text: "Extraia os lançamentos." },
                    { inlineData: { mimeType: mimeType, data: base64Data } }
                ]
            },
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json"
            }
        });

        if (!response.text) throw new Error("A IA não retornou resposta.");

        let jsonResponse;
        try {
            jsonResponse = JSON.parse(response.text);
        } catch (e) {
            throw new Error("A IA retornou formato inválido.");
        }

        return new Response(JSON.stringify(jsonResponse), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
          status: 200,
        });
    }

    throw new Error("Invalid action");

  } catch (error) {
    console.error("Error in 'process-pdf-statement':", error);
    return new Response(JSON.stringify({ error: error.message }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500,
    });
  }
});

import React, { useState, useCallback } from 'react';
import Modal from './Modal';
import { useAppData } from '../../hooks/useAppData';
import { TransactionNature, CategoryType } from '../../types';
import { formatCurrency, formatDate } from '../../utils/formatters';
import { supabase } from '../../supabase/client';
import { UploadCloud, FileText, BadgeCheck, BadgeX, Trash2, Loader2, Banknote, Sparkles, AlertCircle } from 'lucide-react';

interface ParsedTransaction {
    date: string;
    description: string;
    value: number;
    nature: TransactionNature;
    categoryName: string;
}

const TransactionPdfImportModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    transactionType: 'checking_account' | 'credit_card';
}> = ({ isOpen, onClose, transactionType }) => {
    const { accounts, categories, addTransactionsBatch } = useAppData();
    const [file, setFile] = useState<File | null>(null);
    const [parsedTransactions, setParsedTransactions] = useState<ParsedTransaction[]>([]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [stepStatus, setStepStatus] = useState<string>('');

    const resetState = useCallback(() => {
        setFile(null);
        setParsedTransactions([]);
        setIsLoading(false);
        setError(null);
        setStepStatus('');
    }, []);

    const handleClose = useCallback(() => {
        resetState();
        setSelectedAccountId('');
        onClose();
    }, [resetState, onClose]);

    const handleFileSelect = useCallback((selectedFile: File) => {
        if (!selectedFile) return;

        // Limite de 10MB
        const maxSizeInBytes = 10 * 1024 * 1024; 
        if (selectedFile.size > maxSizeInBytes) {
            setError("O arquivo é muito grande (máx 10MB).");
            return;
        }

        setFile(selectedFile);
        setError(null);
    }, []);

    const processPdf = async () => {
        if (!file || !selectedAccountId) return;
        setIsLoading(true);
        setError(null);
        let uploadedPath = '';

        try {
            // FLUXO DE UPLOAD SEGURO (BYPASS RLS):
            // 1. Pedir à Edge Function um token para upload (pois o front não tem permissão de anon)
            setStepStatus('Obtendo permissão de upload...');
            const sanitizedName = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');

            const { data: uploadConfig, error: tokenError } = await supabase.functions.invoke('process-pdf-statement', {
                body: { action: 'get_upload_url', fileName: sanitizedName }
            });

            if (tokenError || !uploadConfig?.token) {
                console.error("Token Error:", tokenError, uploadConfig);
                throw new Error("Falha ao iniciar upload seguro. Verifique a conexão.");
            }

            // 2. Fazer upload direto para o Storage usando o token
            setStepStatus('Enviando arquivo...');
            const { data: uploadResult, error: uploadError } = await supabase.storage
                .from('attachments')
                .uploadToSignedUrl(uploadConfig.path, uploadConfig.token, file);

            if (uploadError) throw new Error(`Erro no upload: ${uploadError.message}`);

            uploadedPath = uploadConfig.path;

            // 3. Processar o arquivo (passando o caminho para a Edge Function baixar internamente)
            setStepStatus('Analisando extrato com IA...');
            const categoryNames = categories.map(c => c.name);

            const { data, error: funcError } = await supabase.functions.invoke('process-pdf-statement', {
                body: { 
                    action: 'process',
                    filePath: uploadedPath, 
                    mimeType: file.type,
                    categoryNames: categoryNames
                }
            });

            if (funcError) {
                console.error("Analysis Error:", funcError);
                throw new Error("A IA falhou ao processar o arquivo.");
            }

            if (data.error) throw new Error(data.error);

            if (!Array.isArray(data.transactions)) {
                throw new Error("Formato de resposta inválido da IA.");
            }

            setParsedTransactions(data.transactions);
            setIsLoading(false);
            setStepStatus('');

        } catch (err: any) {
            console.error("Erro ao processar PDF:", err);
            setError(err.message || "Erro desconhecido ao processar o PDF.");
            setIsLoading(false);
            setStepStatus('');
        } finally {
            // 4. Limpeza (opcional, pode ser mantido para debug ou removido)
            if (uploadedPath) {
                 // Para remover, precisaríamos de outro endpoint admin, 
                 // então deixaremos o arquivo na pasta temp por enquanto (pode-se configurar expiração no bucket)
            }
        }
    };

    const handleImport = async () => {
        const transactionsToImport = parsedTransactions.map(t => {
            const matchedCategory = categories.find(c => c.name.toLowerCase() === t.categoryName?.toLowerCase());
            let finalCategoryId = matchedCategory?.id;

            if (!finalCategoryId) {
                const fallbackCat = categories.find(c => c.type === (t.nature as unknown as CategoryType));
                finalCategoryId = fallbackCat?.id || categories[0]?.id; 
            }

            return {
                accountId: selectedAccountId,
                description: t.description,
                date: t.date,
                value: t.value,
                nature: t.nature,
                categoryId: finalCategoryId,
                type: transactionType
            };
        });

        if (transactionsToImport.length === 0) {
            setError('Nenhum lançamento para importar.');
            return;
        }

        setIsLoading(true);
        try {
            await addTransactionsBatch(transactionsToImport);
            alert(`${transactionsToImport.length} lançamentos importados com sucesso!`);
            handleClose();
        } catch (err) {
            setError('Falha ao salvar lançamentos no banco de dados.');
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Modal isOpen={isOpen} onClose={handleClose} title="Importar Extrato PDF com IA">
            <div className="space-y-4">
                <div>
                    <label htmlFor="pdf-account" className="block text-sm font-medium text-gray-700">1. Selecione a Conta / Cartão</label>
                    <div className="relative mt-1">
                        <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                            <Banknote className="h-5 w-5 text-gray-400" />
                        </div>
                        <select
                            id="pdf-account"
                            value={selectedAccountId}
                            onChange={(e) => setSelectedAccountId(e.target.value)}
                            disabled={isLoading && parsedTransactions.length > 0} 
                            className="block w-full rounded-md border-gray-300 pl-10 focus:border-blue-500 focus:ring-blue-500 sm:text-sm p-2 border bg-white disabled:bg-gray-100"
                        >
                            <option value="">Selecione uma conta...</option>
                            {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                        </select>
                    </div>
                </div>

                {!file || (parsedTransactions.length === 0 && !isLoading) ? (
                    <div className={!selectedAccountId ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer hover:border-blue-500 hover:bg-blue-50/50 transition-colors'}>
                        <div
                            onDrop={(e) => { e.preventDefault(); if(selectedAccountId) handleFileSelect(e.dataTransfer.files[0]) }}
                            onDragOver={(e) => e.preventDefault()}
                            onClick={() => { if (selectedAccountId) document.getElementById('pdf-upload')?.click() }}
                            className="border-2 border-dashed border-gray-300 rounded-lg p-8 text-center"
                        >
                            <UploadCloud className="mx-auto h-12 w-12 text-gray-400" />
                            <p className="mt-2 text-sm text-gray-600">
                                {file ? file.name : (selectedAccountId ? '2. Arraste ou clique para selecionar o PDF' : 'Selecione uma conta para continuar')}
                            </p>
                            <p className="text-xs text-gray-400 mt-1">Máximo 10MB</p>
                            <input id="pdf-upload" type="file" accept="application/pdf" className="hidden" disabled={!selectedAccountId} onChange={(e) => e.target.files && handleFileSelect(e.target.files[0])} />
                        </div>
                         {file && (
                             <div className="mt-4 text-center">
                                <button 
                                    onClick={processPdf}
                                    className="inline-flex items-center gap-2 px-6 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 font-semibold shadow transition-colors"
                                >
                                    <Sparkles size={18} />
                                    Processar PDF com IA
                                </button>
                             </div>
                         )}
                    </div>
                ) : null}

                {isLoading && (
                    <div className="space-y-4 text-center p-8 bg-gray-50 rounded-lg">
                        <Loader2 className="mx-auto h-12 w-12 text-blue-600 animate-spin" />
                        <p className="font-semibold text-gray-700">
                           {stepStatus || (parsedTransactions.length > 0 ? 'Salvando...' : 'Processando...')}
                        </p>
                        <p className="text-sm text-gray-500">Aguarde um momento.</p>
                    </div>
                )}

                {parsedTransactions.length > 0 && !isLoading && (
                    <>
                        <div className="flex items-center gap-3 p-3 bg-gray-100 rounded-lg">
                           <FileText className="w-6 h-6 text-blue-600 flex-shrink-0" />
                           <div className="flex-grow">
                               <p className="font-medium text-gray-800">{file?.name}</p>
                               <p className="text-xs text-gray-500">{parsedTransactions.length} lançamentos encontrados.</p>
                           </div>
                           <button onClick={resetState} className="text-sm font-semibold text-blue-600 hover:underline">Reiniciar</button>
                        </div>

                        <div className="max-h-64 overflow-y-auto border rounded-lg">
                            <table className="w-full text-sm">
                                <thead className="bg-gray-50 sticky top-0">
                                    <tr>
                                        <th className="p-2 text-left font-medium text-gray-500">Data</th>
                                        <th className="p-2 text-left font-medium text-gray-500">Descrição</th>
                                        <th className="p-2 text-left font-medium text-gray-500">Categoria (IA)</th>
                                        <th className="p-2 text-right font-medium text-gray-500">Valor</th>
                                        <th className="p-2"></th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {parsedTransactions.map((t, index) => (
                                        <tr key={index} className="border-t">
                                            <td className="p-2 whitespace-nowrap">{t.date ? formatDate(t.date) : '-'}</td>
                                            <td className="p-2 font-medium">{t.description}</td>
                                            <td className="p-2 text-gray-600 italic">{t.categoryName || 'Outros'}</td>
                                            <td className={`p-2 font-semibold text-right ${t.nature === 'RECEITA' ? 'text-green-600' : 'text-red-600'}`}>{formatCurrency(t.value || 0)}</td>
                                            <td className="p-2 text-right">
                                                <button onClick={() => setParsedTransactions(prev => prev.filter((_, i) => i !== index))} className="p-1 text-gray-400 hover:text-red-600 rounded-full">
                                                    <Trash2 size={16} />
                                                </button>
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </>
                )}

                {error && (
                    <div className="flex items-center gap-2 text-sm text-red-600 p-3 bg-red-50 rounded-md border border-red-200">
                        <AlertCircle className="w-5 h-5 flex-shrink-0" />
                        <p>{error}</p>
                    </div>
                )}

                <div className="flex justify-end gap-3 pt-4 border-t mt-4">
                    <button type="button" onClick={handleClose} className="px-4 py-2 bg-gray-200 text-gray-700 rounded-md hover:bg-gray-300">Cancelar</button>
                    <button 
                        type="button"
                        onClick={handleImport}
                        disabled={isLoading || parsedTransactions.length === 0}
                        className="flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 font-semibold shadow disabled:bg-blue-300 disabled:cursor-not-allowed"
                    >
                        Confirmar Importação
                    </button>
                </div>
            </div>
        </Modal>
    );
};

export default TransactionPdfImportModal;

