// NOTA: Este arquivo deve estar em `supabase/functions/process-pdf-statement/index.ts`
import { GoogleGenAI } from "https://esm.sh/@google/genai@0.12.0";
import { encodeBase64, decodeBase64 } from "https://deno.land/std@0.224.0/encoding/base64.ts";
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.43.4';

declare const Deno: any;

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
};

const GEMINI_API_KEY = Deno.env.get("GEMINI_API_KEY");
const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

const generateSystemInstruction = (categoryNames: string[]) => {
    const categoriesStr = categoryNames && categoryNames.length > 0 ? categoryNames.join(', ') : 'Alimentação, Transporte, Moradia, Saúde, Lazer, Outros';
    return `
    Você é um especialista em contabilidade e extração de dados bancários.
    Sua tarefa é analisar o arquivo PDF fornecido e extrair todos os lançamentos financeiros.

    Regras:
    1. Ignore linhas de saldo, saldo anterior ou resumo. Foque apenas nas transações individuais.
    2. Identifique DATA (YYYY-MM-DD), DESCRIÇÃO, VALOR (numérico) e NATUREZA ('RECEITA' ou 'DESPESA').
    3. Banco do Brasil/Itaú/Bradesco: 'C' ou créditos = Receita, 'D' ou débitos = Despesa.
    4. Categorize baseado em: [${categoriesStr}]. Se incerto, use 'Outros'.

    Saída JSON:
    {
      "transactions": [
        { "date": "2024-05-12", "description": "MERCADO", "value": 150.50, "nature": "DESPESA", "categoryName": "Alimentação" }
      ]
    }
    `;
};

const analyzeWithGemini = async (base64Data: string, mimeType: string, systemInstruction: string) => {
    console.log(`[Gemini] Starting analysis. MimeType: ${mimeType}, Base64 Length: ${base64Data.length}`);
    const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });

    try {
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview', 
            contents: {
                parts: [
                    { text: "Extraia os lançamentos." },
                    { inlineData: { mimeType: mimeType, data: base64Data } }
                ]
            },
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json"
            }
        });

        if (!response.text) {
             console.error("[Gemini] No response text received.");
             throw new Error("A IA não retornou resposta.");
        }

        console.log(`[Gemini] Raw Response Preview: ${response.text.substring(0, 300)}...`);

        try {
            return JSON.parse(response.text);
        } catch (e) {
            console.error(`[Gemini] JSON Parse Error. Raw text:`, response.text);
            throw new Error(`A IA retornou formato inválido: ${response.text.substring(0, 100)}...`);
        }
    } catch (apiError) {
        console.error("[Gemini] API Call Error:", apiError);
        throw apiError;
    }
};


Deno.serve(async (req) => {
  // Log básico de entrada
  console.log(`[Request] Method: ${req.method} URL: ${req.url}`);

  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    if (!GEMINI_API_KEY || !SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
      console.error("[Env] Missing keys:", { hasGemini: !!GEMINI_API_KEY, hasSupabaseUrl: !!SUPABASE_URL, hasServiceKey: !!SUPABASE_SERVICE_ROLE_KEY });
      throw new Error("Missing env vars: GEMINI_API_KEY, SUPABASE_URL, or SUPABASE_SERVICE_ROLE_KEY");
    }

    const requestData = await req.json();
    const { action } = requestData;
    console.log(`[Action] ${action}`);

    // --- AÇÃO 1: Processamento Direto (para arquivos PEQUENOS, ex: < 500KB) ---
    if (action === 'process_payload') {
        const { fileData, mimeType, categoryNames, fileName } = requestData;
        if (!fileData || !mimeType) throw new Error("fileData and mimeType required");
        console.log(`[Process Payload] Size: ${fileData.length}, Type: ${mimeType}`);

        const supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

        // Tentativa de salvar backup
        try {
            const filePath = `temp/direct-${crypto.randomUUID()}-${fileName || 'upload.pdf'}`;
            const fileBuffer = decodeBase64(fileData);

            const { error: uploadError } = await supabaseAdmin.storage
                .from('attachments')
                .upload(filePath, fileBuffer, { contentType: mimeType });

            if (uploadError) console.warn("Aviso: Falha ao salvar backup no storage (process_payload):", uploadError);
            else console.log(`[Backup] Saved to ${filePath}`);
        } catch (e) {
            console.warn("Aviso: Erro interno ao salvar backup:", e);
        }

        const jsonResponse = await analyzeWithGemini(fileData, mimeType, generateSystemInstruction(categoryNames));

        return new Response(JSON.stringify(jsonResponse), {
            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
            status: 200,
        });
    }

    // --- AÇÃO 2: Gerar URL de Upload Assinada ---
    if (action === 'get_upload_url') {
        const { fileName } = requestData;
        if (!fileName) throw new Error("fileName is required for get_upload_url");

        const supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
        const filePath = `temp/${crypto.randomUUID()}-${fileName}`;
        console.log(`[Get Upload URL] Generating for path: ${filePath}`);

        const { data, error } = await supabaseAdmin.storage
            .from('attachments')
            .createSignedUploadUrl(filePath);

        if (error) {
            console.error("[Get Upload URL] Error creating signed URL:", error);
            throw error;
        }

        return new Response(JSON.stringify({ 
            token: data.token, 
            path: data.path,
            signedUrl: data.signedUrl 
        }), {
            headers: { ...corsHeaders, 'Content-Type': 'application/json' },
            status: 200,
        });
    }

    // --- AÇÃO 3: Processar Arquivo já no Storage (Via Path) ---
    if (action === 'process') {
        const { filePath, mimeType, categoryNames } = requestData;
        if (!filePath || !mimeType) throw new Error("filePath and mimeType required");
        console.log(`[Process] Downloading from storage: ${filePath}`);

        const supabaseAdmin = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

        // Baixa o arquivo usando credenciais de admin
        const { data: fileData, error: downloadError } = await supabaseAdmin.storage
            .from('attachments')
            .download(filePath);

        if (downloadError) {
             console.error("[Process] Storage Download Error:", downloadError);
             throw new Error(`Failed to download file from storage: ${downloadError.message}`);
        }

        const arrayBuffer = await fileData.arrayBuffer();
        console.log(`[Process] File downloaded. Size: ${arrayBuffer.byteLength} bytes`);

        const base64Data = encodeBase64(arrayBuffer);

        const jsonResponse = await analyzeWithGemini(base64Data, mimeType, generateSystemInstruction(categoryNames));

        return new Response(JSON.stringify(jsonResponse), {
          headers: { ...corsHeaders, 'Content-Type': 'application/json' },
          status: 200,
        });
    }

    throw new Error(`Invalid action: ${action}`);

  } catch (error) {
    console.error("[Edge Function Error]", error);
    return new Response(JSON.stringify({ error: error.message || "Internal Server Error" }), {
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
      status: 500,
    });
  }
});

import React, { useState, useCallback } from 'react';
import Modal from './Modal';
import { useAppData } from '../../hooks/useAppData';
import { TransactionNature, CategoryType } from '../../types';
import { formatCurrency, formatDate } from '../../utils/formatters';
import { supabase } from '../../supabase/client';
import { UploadCloud, FileText, BadgeCheck, BadgeX, Trash2, Loader2, Banknote, Sparkles, AlertCircle } from 'lucide-react';

interface ParsedTransaction {
    date: string;
    description: string;
    value: number;
    nature: TransactionNature;
    categoryName: string;
}

const TransactionPdfImportModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    transactionType: 'checking_account' | 'credit_card';
}> = ({ isOpen, onClose, transactionType }) => {
    const { accounts, categories, addTransactionsBatch } = useAppData();
    const [file, setFile] = useState<File | null>(null);
    const [parsedTransactions, setParsedTransactions] = useState<ParsedTransaction[]>([]);
    const [selectedAccountId, setSelectedAccountId] = useState<string>('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [stepStatus, setStepStatus] = useState<string>('');

    const resetState = useCallback(() => {
        setFile(null);
        setParsedTransactions([]);
        setIsLoading(false);
        setError(null);
        setStepStatus('');
    }, []);

    const handleClose = useCallback(() => {
        resetState();
        setSelectedAccountId('');
        onClose();
    }, [resetState, onClose]);

    const handleFileSelect = useCallback((selectedFile: File) => {
        if (!selectedFile) return;

        console.log(`[PDF Import] Arquivo selecionado: ${selectedFile.name}, Tamanho: ${selectedFile.size} bytes`);

        // Limite de 10MB
        const maxSizeInBytes = 10 * 1024 * 1024; 
        if (selectedFile.size > maxSizeInBytes) {
            console.warn(`[PDF Import] Arquivo muito grande: ${selectedFile.size}`);
            setError("O arquivo é muito grande (máx 10MB).");
            return;
        }

        setFile(selectedFile);
        setError(null);
    }, []);

    const processPdf = async () => {
        if (!file || !selectedAccountId) return;
        setIsLoading(true);
        setError(null);
        setStepStatus('Iniciando upload direto...');

        console.group('Processamento de PDF - Início');
        console.log('[Step 0] Conta selecionada:', selectedAccountId);

        try {
            const categoryNames = categories.map(c => c.name);
            const sanitizedName = file.name.replace(/[^a-zA-Z0-9.-]/g, '_');

            // 1. Upload Direto para o Storage (Pasta Public para compatibilidade com AppContext)
            // Isso evita a necessidade de chamar a Edge Function apenas para pegar permissão.
            setStepStatus('Enviando arquivo para a nuvem...');
            const storagePath = `public/${crypto.randomUUID()}-${sanitizedName}`;

            console.log('[Step 1] Iniciando upload direto para:', storagePath);

            const { data: uploadData, error: uploadError } = await supabase.storage
                .from('attachments')
                .upload(storagePath, file);

            if (uploadError) {
                console.error("[Step 1 Error] Erro no upload direto:", uploadError);
                throw new Error(`Erro no envio do arquivo: ${uploadError.message}`);
            }
            console.log('[Step 1 Success] Upload concluído. Path:', uploadData.path);

            // 2. Processamento via IA (Envia apenas o caminho do arquivo)
            setStepStatus('IA analisando extrato...');
            console.log('[Step 2] Solicitando análise da IA...');

            const { data, error: funcError } = await supabase.functions.invoke('process-pdf-statement', {
                body: { 
                    action: 'process',
                    filePath: uploadData.path, 
                    mimeType: file.type,
                    categoryNames
                }
            });

            if (funcError) {
                 console.error("[Step 2 Error] Erro na invocação da IA:", funcError);
                 // Tenta limpar o arquivo se a função falhar
                 await supabase.storage.from('attachments').remove([uploadData.path]);
                 throw new Error(`Falha ao comunicar com a IA: ${funcError.message}`);
            }

            console.log('[Step 2 Success] Resposta da IA:', data);

            if (data?.error) {
                 console.error("[Step 2 Logic Error] A IA retornou erro:", data.error);
                 throw new Error(`Erro da IA: ${data.error}`);
            }

            if (!data || !data.transactions) {
                console.error("[Step 2 Logic Error] Formato inesperado:", data);
                throw new Error("A IA não retornou transações válidas.");
            }

            setParsedTransactions(data.transactions);

            // Opcional: Limpar arquivo após processamento bem sucedido para economizar espaço?
            // Por enquanto mantemos para auditoria ou debugging se necessário, ou podemos deletar aqui.
            // await supabase.storage.from('attachments').remove([uploadData.path]);

            setIsLoading(false);
            setStepStatus('');
            console.log('[Final] Processamento concluído com sucesso.');

        } catch (err: any) {
            console.error("[PDF Import Critical Error]", err);
            setError(err.message || "Erro desconhecido ao processar o PDF.");
            setIsLoading(false);
            setStepStatus('');
        } finally {
            console.groupEnd();
        }
    };

    const handleImport = async () => {
        const transactionsToImport = parsedTransactions.map(t => {
            const matchedCategory = categories.find(c => c.name.toLowerCase() === t.categoryName?.toLowerCase());
            let finalCategoryId = matchedCategory?.id;

            if (!finalCategoryId) {
                const fallbackCat = categories.find(c => c.type === (t.nature as unknown as CategoryType));
                finalCategoryId = fallbackCat?.id || categories[0]?.id; 
            }

            return {
                accountId: selectedAccountId,
                description: t.description,
                date: t.date,
                value: t.value,
                nature: t.nature,
                categoryId: finalCategoryId,
                type: transactionType
            };
        });

        if (transactionsToImport.length === 0) {
            setError('Nenhum lançamento para importar.');
            return;
        }

        setIsLoading(true);
        try {
            await addTransactionsBatch(transactionsToImport);
            alert(`${transactionsToImport.length} lançamentos importados com sucesso!`);
            handleClose();
        } catch (err) {
            console.error("Erro ao salvar no banco:", err);
            setError('Falha ao salvar lançamentos no banco de dados.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Modal isOpen={isOpen} onClose={handleClose} title="Importar Extrato PDF com IA">
            <div className="space-y-4">
                <div>
                    <label htmlFor="pdf-account" className="block text-sm font-medium text-gray-700">1. Selecione a Conta / Cartão</label>
                    <div className="relative mt-1">
                        <div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                            <Banknote className="h-5 w-5 text-gray-400" />
                        </div>
                        <select
                            id="pdf-account"
                            value={selectedAccountId}
                            onChange={(e) => setSelectedAccountId(e.target.value)}
                            disabled={isLoading && parsedTransactions.length > 0} 
                            className="block w-full rounded-md border-gray-300 pl-10 focus:border-blue-500 focus:ring-blue-500 sm:text-sm p-2 border bg-white disabled:bg-gray-100"
                        >
                            <option value="">Selecione uma conta...</option>
                            {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name}</option>)}
                        </select>
                    </div>
                </div>

                {!file ? (
                    <div className="space-y-4 text-center">
                        <div
                            onDrop={(e) => { e.preventDefault(); if(selectedAccountId) handleFileSelect(e.dataTransfer.files[0]) }}
                            onDragOver={(e) => e.preventDefault()}
                            onClick={() => { if (selectedAccountId) document.getElementById('pdf-upload')?.click() }}
                            className={`border-2 border-dashed border-gray-300 rounded-lg p-8 text-center transition-colors ${!selectedAccountId ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer hover:border-blue-500 hover:bg-blue-50/50'}`}
                        >
                            <UploadCloud className="mx-auto h-12 w-12 text-gray-400" />
                            <p className="mt-2 text-sm text-gray-600">
                                {selectedAccountId ? '2. Arraste ou clique para selecionar o PDF' : 'Selecione uma conta para continuar'}
                            </p>
                            <p className="text-xs text-gray-400 mt-1">Máximo 10MB</p>
                            <input id="pdf-upload" type="file" accept="application/pdf" className="hidden" disabled={!selectedAccountId} onChange={(e) => e.target.files && handleFileSelect(e.target.files[0])} />
                        </div>
                    </div>
                ) : (
                    <>
                        <div className="flex items-center gap-3 p-3 bg-gray-100 rounded-lg">
                           <FileText className="w-6 h-6 text-blue-600 flex-shrink-0" />
                           <div className="flex-grow">
                               <p className="font-medium text-gray-800">{file.name}</p>
                               <p className="text-xs text-gray-500">
                                   {parsedTransactions.length > 0 
